import crypto from 'node:crypto';
import { Logger } from '../logging/Logger.js';
export class ConnectionManager {
    config; storage; client; pairing; discovery; heartbeat; reconnect; logger; state = 'UNPAIRED'; heartbeatTimer = null; lastError = null;
    constructor(config, storage, client, pairing, discovery, heartbeat, reconnect, logger = new Logger(config.logLevel)) { this.config=config; this.storage=storage; this.client=client; this.pairing=pairing; this.discovery=discovery; this.heartbeat=heartbeat; this.reconnect=reconnect; this.logger=logger; }
    async start(){ const restored=await this.client.restorePairing(); this.transition(restored?'DEGRADED':'UNPAIRED'); if(restored){ this.logger.info('connection.restored',{instanceId:this.client.currentIntegration()?.integration_uuid}); await this.reconnect.start(); await this.discovery.sync(true); await this.sendHeartbeatCycle(); this.startHeartbeatLoop(); } }
    stop(){ if(this.heartbeatTimer){ clearInterval(this.heartbeatTimer); this.heartbeatTimer=null; } }
    async connect(input){ this.transition('PAIRING'); this.logger.info('pair.started'); const result=await this.pairing.pair(input); this.logger.info('pair.credentials_saved',{instanceId:result.instanceId}); try{ this.transition('CHALLENGING'); const challengeCompleted=await this.challenge(); if(!challengeCompleted){ await this.storage.clearIntegration(); this.client.clearPairing(); this.transition('UNPAIRED'); throw new Error('Challenge failed after pairing. Pairing was cancelled.'); } this.transition('DISCOVERING'); const discoveryCompleted=await this.discovery.sync(true); if(!discoveryCompleted){ this.transition('DEGRADED'); this.logger.warn('discovery.incomplete',{reason:this.discovery.lastError||'not_completed'}); } this.transition('CONNECTING'); const heartbeatCompleted=await this.sendHeartbeatCycle(); this.startHeartbeatLoop(); if(heartbeatCompleted&&discoveryCompleted){ this.transition('CONNECTED'); this.logger.info('connected.confirmed',{instanceId:this.client.currentIntegration()?.integration_uuid}); } else this.transition('DEGRADED'); const snapshot=this.status(); return { success: snapshot.state==='CONNECTED'||snapshot.state==='DEGRADED', ready:snapshot.state==='CONNECTED', state:snapshot.state, paired:snapshot.paired, instanceId:snapshot.instanceId, protocolVersion:snapshot.protocolVersion, pairedAt:result.pairedAt, challengeCompleted, discoveryCompleted, heartbeatCompleted, platformConnected:snapshot.platformConnected, capabilities:snapshot.capabilities, workflows:snapshot.workflows, lastHeartbeatAt:snapshot.lastHeartbeatAt, lastDiscoveryAt:snapshot.lastDiscoveryAt, latencyMs:snapshot.latencyMs }; } catch(error){ this.lastError=error instanceof Error?error.message:'Unknown connection error'; this.logger.error('connection.failed',{stage:this.state,error:this.lastError}); throw error; } }
    async disconnect(){ this.stop(); await this.storage.clearIntegration(); this.client.clearPairing(); this.heartbeat.status='unpaired'; this.transition('UNPAIRED'); }
    async reconnectWithPairCode(input){ return this.connect(input); }
    async rotateSecret(){ this.transition('SECRET_ROTATION_PENDING'); this.logger.info('secret_rotation.started'); const integration=this.client.currentIntegration()??await this.storage.readIntegration(); if(!integration){ this.transition('UNPAIRED'); throw new Error('Agent is unpaired. Cannot rotate secret.'); } const response=await this.client.signed('POST','/api/v1/integrations/n8n/secret/rotate'); const data=response.data; if(!data?.shared_secret) throw new Error('Platform did not return a pending secret.'); integration.shared_secret=data.shared_secret; integration.secret_version+=1; await this.storage.saveIntegration(integration); this.client.setPairing(integration); await this.client.signed('POST','/api/v1/integrations/n8n/secret/confirm'); const heartbeatCompleted=await this.sendHeartbeatCycle(); this.transition(heartbeatCompleted?'CONNECTED':'DEGRADED'); this.startHeartbeatLoop(); this.logger.info('secret_rotation.completed',{instanceId:integration.integration_uuid}); return {success:true,state:this.state,heartbeatCompleted}; }
    async testConnection(){ const challengeCompleted=await this.challenge(); const heartbeatCompleted=await this.sendHeartbeatCycle(); const snapshot=this.status(); return {success:challengeCompleted&&heartbeatCompleted&&snapshot.capabilities>0,state:snapshot.state,paired:snapshot.paired,platformConnected:snapshot.platformConnected,challengeCompleted,heartbeatCompleted,capabilities:snapshot.capabilities,workflows:snapshot.workflows,latencyMs:snapshot.latencyMs,lastError:snapshot.lastError}; }
    status(){ const integration=this.client.currentIntegration(); const heartbeatAgeSeconds=this.heartbeat.lastHeartbeatAt?Math.max(0,Math.round((Date.now()-Date.parse(this.heartbeat.lastHeartbeatAt))/1000)):null; return {state:this.stateForCurrentHealth(),paired:this.client.isPaired(),platformConnected:this.heartbeat.status==='connected',instanceId:integration?.integration_uuid||null,protocolVersion:integration?.protocol_version||'1.0',lastHeartbeatAt:this.heartbeat.lastHeartbeatAt,lastDiscoveryAt:this.discovery.lastDiscoveryAt,heartbeatAgeSeconds,latencyMs:this.heartbeat.latencyMs,capabilities:this.discovery.capabilityCount,workflows:this.discovery.workflowCount,lastError:this.lastError||this.heartbeat.lastError||this.discovery.lastError}; }
    async challenge(){ const integration=this.client.currentIntegration()??await this.storage.readIntegration(); if(!integration){ this.lastError='Agent is unpaired.'; return false; } this.client.setPairing(integration); try{ await this.client.signed('POST', integration.challenge_url||'/api/v1/integrations/n8n/challenge', {challenge:crypto.randomUUID(),sent_at:new Date().toISOString()}); this.logger.info('challenge.validated',{instanceId:integration.integration_uuid}); this.lastError=null; return true; } catch(error){ this.lastError=error instanceof Error?error.message:'Unknown challenge error'; this.logger.error('challenge.failed',{instanceId:integration.integration_uuid,error:this.lastError}); return false; } }
    async sendHeartbeatCycle(){ const ok=await this.heartbeat.send(); if(ok){ this.transition('CONNECTED'); this.logger.info('heartbeat.ok',{latencyMs:this.heartbeat.latencyMs}); return true; } if(this.heartbeat.status==='requires_repairing'){ this.transition('UNAUTHORIZED'); this.stop(); } else if(this.heartbeat.status==='disconnected') this.transition('DISCONNECTED'); else if(this.client.isPaired()) this.transition('DEGRADED'); return false; }
    startHeartbeatLoop(){ if(this.heartbeatTimer) return; this.heartbeatTimer=setInterval(()=>{ void this.sendHeartbeatCycle(); }, this.config.heartbeatSeconds*1000); }
    stateForCurrentHealth(){ if(!this.client.isPaired()) return 'UNPAIRED'; if(this.heartbeat.status==='requires_repairing') return 'UNAUTHORIZED'; if(this.heartbeat.status==='connected') return 'CONNECTED'; if(this.heartbeat.status==='disconnected') return 'DISCONNECTED'; return this.state; }
    transition(next){ if(this.state===next) return; const previous=this.state; this.state=next; this.logger.info('connection.state_changed',{previous,next}); }
}
